SELECT 
FROM fbs_plan_policy_revision_receipt r
WHERE BINARY r.product_code = BINARY #{productCode}
  AND BINARY r.actor_type = BINARY #{actorType}
  AND r.actor_user_id = #{actorUserId}
  AND BINARY r.idempotency_key_digest = BINARY #{idempotencyKeyDigest}

SELECT 
FROM fbs_plan_policy_revision_receipt r
WHERE BINARY r.product_code = BINARY #{productCode}
  AND BINARY r.receipt_id = BINARY #{receiptId}

mapper.update:
UPDATE fbs_plan_policy_head
SET active_receipt_id = #{nextReceiptId},
    policy_version = #{nextVersion},
    updated_at = GREATEST(updated_at, #{updatedAt})
WHERE BINARY product_code = BINARY #{productCode}
  AND BINARY plan_code = BINARY #{planCode}
  AND BINARY active_receipt_id = BINARY #{expectedReceiptId}
  AND policy_version = #{expectedVersion}

mapper.select:
SELECT 
FROM fbs_plan_policy_revision_receipt r
WHERE BINARY r.product_code = BINARY #{productCode}
ORDER BY r.created_at DESC, r.id DESC
LIMIT #{limit}
